import assert from "node:assert/strict"
import { readFileSync, readdirSync } from "node:fs"
import { resolve } from "node:path"
import { JSDOM } from "jsdom"
import { invoke } from "@tauri-apps/api/core"
import { getVersion } from "@tauri-apps/api/app"
import { listen } from "@tauri-apps/api/event"
import { mockIPC, mockWindows } from "@tauri-apps/api/mocks"
import { getCurrentWindow } from "@tauri-apps/api/window"
import { open } from "@tauri-apps/plugin-shell"
import { check } from "@tauri-apps/plugin-updater"
import { createAppMenu } from "../../src/lib/appMenu"
import { runPreparedUpdate } from "../../src/lib/gracefulShutdown"

// Resolve the checked-in ACL manifests generated by the native build. Exercise
// real SDK calls against those grants without opening URLs or installing updates.
const root = resolve(import.meta.dir, "../..")
const readJson = (file: string) =>
  JSON.parse(readFileSync(resolve(root, file), "utf8"))
const config = readJson("src-tauri/tauri.conf.json")
const manifests = readJson("src-tauri/gen/schemas/acl-manifests.json")
const capabilities = readdirSync(resolve(root, "src-tauri/capabilities"))
  .filter((file) => file.endsWith(".json"))
  .map((file) => readJson(`src-tauri/capabilities/${file}`))
const selected = config.app.security.capabilities
  ? config.app.security.capabilities.map((id: string) => {
      const capability = capabilities.find((item) => item.identifier === id)
      assert.ok(capability, `Unknown capability ${id}`)
      return capability
    })
  : capabilities
const allowed = new Set<string>()
const denied = new Set<string>()

function resolvePermission(id: string, parents: string[] = []) {
  assert.ok(!parents.includes(id), `Cyclic permission set ${id}`)
  const colon = id.lastIndexOf(":")
  const namespace = id.slice(0, colon)
  const name = id.slice(colon + 1)
  const manifest = manifests[namespace]
  assert.ok(manifest, `Unknown plugin namespace ${namespace}`)
  const set =
    name === "default"
      ? manifest.default_permission
      : manifest.permission_sets[name]
  if (set) {
    for (const member of set.permissions) {
      resolvePermission(
        member.includes(":") ? member : `${namespace}:${member}`,
        [...parents, id]
      )
    }
    return
  }
  const permission = manifest.permissions[name]
  assert.ok(permission, `Unknown permission ${id}`)
  const plugin = namespace.startsWith("core:") ? namespace.slice(5) : namespace
  for (const command of permission.commands.allow)
    allowed.add(`plugin:${plugin}|${command}`)
  for (const command of permission.commands.deny)
    denied.add(`plugin:${plugin}|${command}`)
}

for (const capability of selected) {
  for (const permission of capability.permissions) {
    resolvePermission(
      typeof permission === "string" ? permission : permission.identifier
    )
  }
}
const permitted = (command: string) =>
  allowed.has(command) && !denied.has(command)

const dom = new JSDOM("", { url: "https://hibiki.example.test" })
Object.assign(globalThis, { window: dom.window, document: dom.window.document })
const calls: string[] = []
let nextResource = 1
let settingsAction: (() => void) | undefined
mockIPC((command, args: any) => {
  assert.ok(permitted(command), `IPC permission denied: ${command}`)
  calls.push(command)
  switch (command) {
    case "plugin:app|version":
      return "0.5.2"
    case "plugin:window|is_maximized":
      return false
    case "plugin:event|listen":
      return nextResource++
    case "plugin:menu|new": {
      const rid = nextResource++
      if (args.options?.id === "settings")
        settingsAction = () => args.handler.onmessage("settings")
      return [rid, args.options?.id ?? `menu-${rid}`]
    }
    case "plugin:menu|set_as_app_menu":
      return null
    case "plugin:updater|check":
      return { rid: nextResource++, currentVersion: "0.5.1", version: "0.5.2" }
    case "plugin:updater|download":
      return nextResource++
  }
})
mockWindows("main")

try {
  if (process.argv[2] === "features") {
    assert.equal(await getVersion(), "0.5.2")
    const win = getCurrentWindow()
    assert.equal(await win.isMaximized(), false)
    const resized = await win.onResized(() => {})
    await resized()
    await win.startDragging()
    // Tauri's injected drag-region script uses this command on double-click.
    await invoke("plugin:window|internal_toggle_maximize")
    await win.minimize()
    await win.toggleMaximize()
    await win.close()
    const unlisten = await listen("audio://position", () => {})
    await unlisten()
    let openedSettings = false
    await createAppMenu(() => {
      openedSettings = true
    })
    assert.ok(settingsAction, "Settings menu action was registered")
    settingsAction()
    assert.equal(openedSettings, true)
    await open("https://app.plex.tv/auth")
    const update = await check()
    assert.ok(update)
    const start = calls.length
    await runPreparedUpdate({
      download: () => update.download(),
      prepareExit: async () => { calls.push("fixture:prepare_exit") },
      install: () => update.install(),
      resume: async () => { calls.push("fixture:resume") },
    })
    assert.deepEqual(calls.slice(start), [
      "plugin:updater|download", "fixture:prepare_exit",
      "plugin:updater|install", "fixture:resume",
    ])
    await update.close()
    // The notification plugin's injected Notification implementation uses these
    // commands, including its startup permission probe on macOS and Linux.
    await invoke("plugin:notification|is_permission_granted")
    await invoke("plugin:notification|request_permission")
    await invoke("plugin:notification|notify", {
      options: { title: "Playing" },
    })
    for (const command of [
      "plugin:event|unlisten",
      "plugin:menu|set_as_app_menu",
      "plugin:resources|close",
    ]) {
      assert.ok(calls.includes(command), `SDK did not exercise ${command}`)
    }
  } else if (process.argv[2] === "boundaries") {
    // These operations have no frontend feature requiring native access.
    for (const command of [
      "plugin:window|destroy",
      "plugin:window|set_cursor_grab",
      "plugin:window|set_ignore_cursor_events",
      "plugin:window|set_always_on_top",
      "plugin:window|set_content_protected",
      "plugin:webview|create_webview_window",
      "plugin:webview|clear_all_browsing_data",
      "plugin:path|resolve_directory",
      "plugin:image|from_path",
      "plugin:tray|new",
      "plugin:event|emit",
      "plugin:event|emit_to",
      "plugin:shell|execute",
      "plugin:shell|spawn",
      "plugin:window-state|save_window_state",
      "plugin:window-state|restore_state",
      "plugin:updater|download_and_install",
      "plugin:notification|cancel",
      "plugin:notification|register_listener",
    ]) {
      await assert.rejects(invoke(command), /IPC permission denied/)
    }
  } else if (process.argv[2] === "scope") {
    assert.ok(
      config.app.security.capabilities?.length,
      "Select capabilities explicitly"
    )
    for (const capability of selected) {
      assert.deepEqual(capability.windows, ["main"])
      assert.equal(capability.remote, undefined)
      assert.notEqual(capability.local, false)
      assert.ok(!capability.webviews?.length, "Do not grant all webviews")
    }
  } else {
    throw new Error("Unknown test scenario")
  }
  console.log("Capability scenario passed")
} finally {
  dom.window.close()
}
